(()=>{
  "use strict";

  const GEM_TYPES=[
    {name:"Azure Insight",color:"#55dcff",trait:"Observation",effect:"Adds one extra evidence note to the specimen record."},
    {name:"Emerald Growth",color:"#53ef9d",trait:"Life",effect:"Stores biological energy for a future Garden upgrade."},
    {name:"Amber Charge",color:"#ffc84f",trait:"Energy",effect:"Stores power for a future ship or laboratory upgrade."},
    {name:"Violet Memory",color:"#b985ff",trait:"Memory",effect:"Preserves a vocabulary clue in the research archive."},
    {name:"Rose Rescue",color:"#ff74a7",trait:"Recovery",effect:"Stores recovery energy for a future rescue mission."},
    {name:"Silver Navigation",color:"#c7e8ff",trait:"Navigation",effect:"Stores route data for a future planetary journey."}
  ];

  const CATALOG=[
    {id:"dam-field-model",name:"Beaver Dam Field Model",rarity:"common",cost:1,image:"assets/science-beaver-field-report-v2.png",origin:"Earth Research · Beaver Wetland",category:"Habitat model",ability:"Displays how a dam changes flowing water into a calm pond.",lesson:"Beavers place branches, stones and mud across a stream. The barrier slows the current, so deeper water collects behind it and creates safer habitat.",facts:["A dam changes water flow rather than creating water.","The new pond can provide shelter for many wetland organisms."]},
    {id:"pollinator-lens",name:"Pollinator Observation Lens",rarity:"common",cost:1,image:"assets/science-bee-orchard-pollination-v1.png",origin:"Earth Research · Bee Orchard",category:"Observation tool",ability:"Highlights pollen moving between flowers.",lesson:"A pollinator carries pollen from the anther of one flower to another flower. This transfer can help an ovule become a seed and the ovary develop into fruit.",facts:["Bees collect nectar for energy and pollen as a protein-rich food.","A flower can reward its pollinator while the pollinator helps the plant reproduce."]},
    {id:"wetland-filter",name:"Wetland Water Filter",rarity:"rare",cost:2,image:"assets/science-wetland-effects-v2.png",origin:"Earth Research · Wetland Balance",category:"Ecosystem instrument",ability:"Models slower water, trapped silt and reduced erosion.",lesson:"A wetland can slow moving water. When water slows, some suspended soil settles as silt, while plant roots help hold the bank together.",facts:["Wetlands can reduce erosion and provide habitat at the same time.","Clearer downstream water is an effect of particles settling, not the disappearance of matter."]},
    {id:"pond-web-projector",name:"Pond Food-Web Projector",rarity:"rare",cost:2,image:"assets/science-pond-food-web-v1.png",origin:"Earth Research · Freshwater Ecosystem",category:"Energy map",ability:"Projects several connected feeding paths in one pond.",lesson:"A food web combines several food chains. Its arrows show the direction energy moves—from the organism being eaten toward the organism that eats it.",facts:["One organism may be part of several food chains.","Removing one population can affect several other populations in the web."]},
    {id:"living-soil-core",name:"Living Soil Research Core",rarity:"legendary",cost:3,image:"assets/science-soil-ecosystem-v1.png",origin:"Earth Research · Living Soil",category:"Laboratory core",ability:"Scans moisture, tunnels, roots and decomposers below ground.",lesson:"Healthy soil is an ecosystem. Earthworms burrow and aerate it, decomposers recycle organic matter, and roots absorb water and nutrients through the spaces between particles.",facts:["Earthworm tunnels help both air and water move through soil.","Castings contain processed material that can add useful nutrients.","Soil is home to a community, not just a pile of mineral particles."]},
    {id:"orbital-seed-vault",name:"Orbital Seed Vault",rarity:"legendary",cost:3,image:"assets/science-fruit-week-review-v2.png",origin:"Earth Research · Fruit & Seed Network",category:"Life archive",ability:"Preserves several seed types and their dispersal records.",lesson:"Seeds protect a young plant embryo and often carry stored food. Fruit can protect seeds and help them travel by animals, wind or water.",facts:["A seed begins germination when conditions such as water and warmth are suitable.","Seed dispersal reduces competition with the parent plant.","Some cultivated fruits develop with few or no mature seeds."]},
    {id:"pilot-change",name:"Crew Identity Pass",rarity:"common",cost:1,image:"assets/pilot-penguin-v1.png",origin:"Cockpit Crew System",category:"Cockpit service",ability:"Changes the active pilot between Pico and Mochi.",lesson:"Scientists work in teams. Different explorers can observe the same evidence and still follow the same fair test and safety rules.",facts:["Changing the pilot is visual; both friends have the same learning abilities."],service:"pilot",repeat:true}
  ];

  const SCIENCE_ITEMS={
    "Stream Map":["assets/science-beaver-wetland-v2.png","Week 1 · Day 1","Habitat record","A beaver dam slows a shallow stream. Water gathers behind the barrier and forms a deeper, calmer pond.","The map records the direction of flowing water before and after the dam."],
    "Lodge Blueprint":["assets/science-beaver-lodge-v2.png","Week 1 · Day 2","Animal-home blueprint","A beaver lodge has an underwater entrance and a dry chamber above the water level.","Thick walls help protect the beaver and keep the chamber warmer."],
    "Winter Food Sample":["assets/science-beaver-winter-food-v2.png","Week 1 · Day 3","Plant-food sample","Beavers store branches underwater so they can reach bark and twigs when the pond surface freezes.","The cold water helps keep stored branches close to the lodge."],
    "Wetland Balance Data":["assets/science-wetland-effects-v2.png","Week 1 · Day 4","Ecosystem data","Slower wetland water can reduce erosion and allow fine silt to settle.","Plant roots can hold soil while the pond creates new habitat."],
    "Wetland Core":["assets/science-beaver-field-report-v2.png","Week 1 · Day 5","Research core","A beaver is an ecosystem engineer because its building activity changes habitat for many species.","One structure can provide the beaver with water, food access and protection."],
    "Pollination Sequence":["assets/science-flower-fruit-v2.png","Week 2 · Day 1","Life-cycle record","Pollen transfer can lead to fertilization. Ovules become seeds and the ovary can develop into fruit.","Fruit formation begins in a flower even though the mature fruit may look very different."],
    "Angiosperm Scanner":["assets/science-angiosperm-pollination-v2.png","Week 2 · Day 2","Plant scanner","An angiosperm is a flowering plant whose seeds develop inside an ovary.","Flowers use colour, scent and nectar to attract many pollinators."],
    "Seed Dispersal Map":["assets/science-seed-dispersal-v2.png","Week 2 · Day 3","Route map","Seeds can disperse by wind, water, animals or explosive fruit.","Travelling away from the parent plant can reduce competition for light and water."],
    "Mutation Sample":["assets/science-seedless-fruit-v2.png","Week 2 · Day 4","Genetics sample","A mutation is a change in genetic material and may produce a new trait.","Farmers can select and reproduce useful plant traits over many generations."],
    "Seed Voyager Core":["assets/science-fruit-week-review-v2.png","Week 2 · Day 5","Research core","Fruit protects seeds and can help carry them to a new habitat.","A seed contains a plant embryo and stored material for early growth."],
    "Bee Adaptation Scan":["assets/science-bee-tools-v1.png","Week 3 · Day 1","Animal adaptation scan","A bee's hairy body can collect pollen, while its mouthparts reach nectar.","Body structures are adaptations when they help an organism survive or reproduce."],
    "Honey Process Record":["assets/science-bee-honey-making-v1.png","Week 3 · Day 2","Food-process record","Honeybees collect nectar and reduce its water content inside the hive.","Honey is stored food made from nectar; not every bee species makes a large honey supply."],
    "Bee Species File":["assets/science-bee-compare-v1.png","Week 3 · Day 3","Classification file","Bee species differ in body form, nesting behaviour and social organization.","Similar animals can fill different roles in the same ecosystem."],
    "Orchard Pollination Map":["assets/science-bee-orchard-pollination-v1.png","Week 3 · Day 4","Pollination map","Pollinators help many orchard flowers form fruit.","A productive orchard depends on interactions between plants, animals and suitable weather."],
    "Pollinator Network Core":["assets/science-bee-week-review-v1.png","Week 3 · Day 5","Research core","Pollination is a partnership that connects animal feeding with plant reproduction.","A network is more resilient when several pollinator species can visit the flowers."],
    "Hoarding Route Map":["assets/science-winter-hoard-v1.png","Week 4 · Day 1","Survival map","Some animals store food before winter and return to hidden caches later.","Hoarding moves food through space and time."],
    "Body Energy Scan":["assets/science-winter-fat-energy-v1.png","Week 4 · Day 2","Energy scan","Stored body fat can supply energy when winter food is scarce.","Animals must balance energy gained from food with energy used for warmth and movement."],
    "Winter Metabolism Record":["assets/science-winter-dormancy-v1.png","Week 4 · Day 3","Metabolism record","During hibernation, body processes slow and energy use falls.","Dormancy is an energy-saving state, not simply ordinary sleep."],
    "Migration Route Atlas":["assets/science-winter-migration-v1.png","Week 4 · Day 4","Navigation atlas","Migration is seasonal movement between habitats.","Animals may migrate to find food, breeding sites or safer weather."],
    "Winter Survival Core":["assets/science-winter-review-v1.png","Week 4 · Day 5","Research core","Animals survive winter through different strategies such as migration, dormancy, food storage and insulation.","A successful strategy matches the species and its habitat."],
    "Producer Energy Scan":["assets/science-pond-producers-v1.png","Week 5 · Day 1","Energy scan","Pond plants and algae are producers because they use sunlight to make food.","Most energy entering a pond food web begins with sunlight."],
    "Food Chain Strip":["assets/science-pond-food-chain-v1.png","Week 5 · Day 2","Energy sequence","A food chain shows one path of energy through organisms.","The arrow points from the food toward the consumer receiving the energy."],
    "Pond Web Map":["assets/science-pond-food-web-v1.png","Week 5 · Day 3","Ecosystem map","A food web connects several food chains in one habitat.","One change can travel through several connected feeding relationships."],
    "Nutrient Cycle Sample":["assets/science-pond-decomposers-v1.png","Week 5 · Day 4","Cycle sample","Decomposers break down dead material and return nutrients to the ecosystem.","Matter cycles even though energy flows in one direction."],
    "Freshwater Ecosystem Core":["assets/science-pond-review-v1.png","Week 5 · Day 5","Research core","A freshwater ecosystem includes organisms plus non-living conditions such as light, water and temperature.","Balance depends on producers, consumers and decomposers."],
    "Soil Life Scan":["assets/science-soil-ecosystem-v1.png","Week 6 · Day 1","Underground scan","Soil contains organisms, air, water, organic matter and mineral particles.","A handful of healthy soil can contain a large living community."],
    "Moisture Shield Record":["assets/science-worm-moisture-v1.png","Week 6 · Day 2","Habitat record","An earthworm's soft body needs a cool, moist environment.","Moisture helps an earthworm exchange gases through its skin."],
    "Soil Tunnel Blueprint":["assets/science-worm-soil-work-v1.png","Week 6 · Day 3","Engineering blueprint","Earthworm burrows create spaces for air and water to enter soil.","Burrowing can improve aeration and drainage around roots."],
    "Garden Cycle Map":["assets/science-garden-nutrient-cycle-v1.png","Week 6 · Day 4","Nutrient map","Decomposers turn organic remains into simpler material that can return to soil.","Roots absorb released nutrients and build new plant tissue."],
    "Soil Ecosystem Core":["assets/science-worm-compost-v1.png","Week 6 · Day 5","Research core","Worm composting turns suitable plant scraps into dark, fertile compost.","Glass and plastic cannot become compost because they are not biodegradable organic matter."]
  };

  let active=null;
  const esc=value=>String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[ch]);
  const unique=list=>[...new Set((list||[]).filter(Boolean))];
  const later=(vault,fn,ms)=>{const timer=setTimeout(()=>{vault.timers.delete(timer);if(active===vault)fn()},ms);vault.timers.add(timer);return timer};
  const rarityQuestions=rarity=>rarity==="legendary"?5:rarity==="rare"?3:1;
  const titleRarity=name=>/Core/i.test(name)?"legendary":/Map|Record|Scan|Atlas|Blueprint|Sequence|Data/i.test(name)?"rare":"common";
  const availableGems=state=>(state.gemWorkshop.forged||[]).filter(gem=>!gem.usedBy);
  const fragments=state=>Math.max(0,(Number(state.science.crystals)||0)-(Number(state.gemWorkshop.convertedFragments)||0));

  function profileFor(name){
    const catalog=CATALOG.find(item=>item.name===name);if(catalog)return catalog;
    const science=SCIENCE_ITEMS[name];if(science)return{id:`science-${name}`,name,rarity:titleRarity(name),cost:0,image:science[0],origin:science[1],category:science[2],ability:"Reopens the evidence collected during this lesson.",lesson:science[3],facts:[science[4]]};
    if(/Earth Explorer spaceship/i.test(name))return{id:"earth-ship",name,rarity:"legendary",image:"assets/adventure-ship-v2.png",origin:"Mathematics Rescue Route",category:"Exploration vehicle",ability:"Travels between unlocked planets.",lesson:"A spacecraft combines propulsion, navigation, life support and a strong structure. Every system must work together before launch.",facts:["The completed ship was assembled from ten parts earned through mathematics missions."]};
    if(/tomato/i.test(name))return{id:`garden-${name}`,name,rarity:"rare",image:"assets/science-fruit-week-review-v2.png",origin:"Orbital Garden",category:"Botanical sample",ability:"Records the fruiting stage of a climbing tomato plant.",lesson:"A tomato develops from a flower. Its flexible stem grows like a vine and benefits from a stake or trellis.",facts:["The fruit contains seeds that can begin the next life cycle."]};
    if(/pea/i.test(name))return{id:`garden-${name}`,name,rarity:"rare",image:"assets/science-seed-dispersal-v2.png",origin:"Orbital Garden",category:"Botanical sample",ability:"Records a pea vine and its seed pod.",lesson:"Pea plants use curling tendrils to climb. Each pod is a fruit that protects several seeds.",facts:["The large seed stores food for early germination."]};
    if(/sunflower/i.test(name))return{id:`garden-${name}`,name,rarity:"rare",image:"assets/science-bee-orchard-pollination-v1.png",origin:"Orbital Garden",category:"Botanical sample",ability:"Records a mature seed head.",lesson:"What looks like one sunflower is a flower head made from many small flowers.",facts:["After pollination, many of the tiny flowers can form seeds."]};
    if(/carrot/i.test(name))return{id:`garden-${name}`,name,rarity:"rare",image:"assets/science-garden-nutrient-cycle-v1.png",origin:"Orbital Garden",category:"Botanical sample",ability:"Records energy stored in a thick taproot.",lesson:"A carrot's leaves make food, and the plant stores much of that energy in its enlarged taproot.",facts:["The orange part grows below the soil surface."]};
    if(/blaster|blade/i.test(name))return{id:`weapon-${name}`,name,rarity:"rare",image:"assets/space-robot-boss-v1.png",origin:"Moon Rescue Mission",category:"Energy equipment",ability:"Damages robot armour during rescue missions.",lesson:"Energy weapons transfer stored energy to a target. Their safe use depends on control, aim and protective systems.",facts:["Different future weapons will interact with different robot attributes."]};
    if(/sticker|paint/i.test(name))return{id:`reward-${name}`,name,rarity:"common",image:"assets/adventure-ship-v2.png",origin:"Planetary Rescue Route",category:"Mission record",ability:"Marks an expedition milestone.",lesson:"A mission record shows where an explorer travelled and what evidence was collected there.",facts:["Planetary surfaces provide clues about their history."]};
    if(/engine|comet/i.test(name))return{id:`engine-${name}`,name,rarity:"legendary",image:"assets/adventure-ship-v2.png",origin:"Space Flight Mission",category:"Ship upgrade",ability:"Stores propulsion data for future Engine Room upgrades.",lesson:"A rocket engine pushes exhaust backward, and the reaction pushes the spacecraft forward.",facts:["Changing velocity requires a force, even in space."]};
    return{id:`material-${name}`,name,rarity:/Diamond|Emerald|Topaz|Sapphire|Amethyst/i.test(name)?"legendary":"common",image:"assets/science-knowledge-crystal-v2.png",origin:"Asteroid Mining Mission",category:"Mineral or element",ability:"Can be used in future laboratory synthesis.",lesson:`${name} is stored as a labelled matter sample. Scientists identify materials by properties such as colour, hardness, density, magnetism and reactivity.`,facts:["A material's observable properties help distinguish it from other substances."]};
  }

  function imageCard(profile,extra=""){return`<button class="vault-item-card rarity-${profile.rarity||"common"}" data-vault-item="${esc(profile.name)}"><span class="vault-item-image"><img src="${esc(profile.image)}" alt="${esc(profile.name)} miniature"></span><small>${(profile.rarity||"common").toUpperCase()} ${extra}</small><strong>${esc(profile.name)}</strong><em>Inspect object →</em></button>`}
  function supplyProfile(kind,count,image,lesson){return{id:`supply-${kind}`,name:`${kind} × ${count}`,rarity:"common",image,origin:"Orbital Garden",category:"Garden supply",ability:"Supports plant growth inside the spaceship garden.",lesson,facts:["Plants need a suitable balance of water, air, light, nutrients and space."]}}

  function render(vault){
    const {state}=vault,workshop=state.gemWorkshop,raw=fragments(state),gems=availableGems(state),research=unique(state.science.discoveries),catalogNames=CATALOG.map(item=>item.name),adventure=unique(state.inventory).filter(item=>!research.includes(item)&&item!=="Knowledge Crystal"&&!catalogNames.includes(item)),rewards=CATALOG.filter(item=>workshop.owned.includes(item.id)),materials=unique(state.materials),supplies=[
      supplyProfile("Soil packs",state.garden.soil,"assets/science-soil-ecosystem-v1.png","Soil anchors roots and stores both water and mineral nutrients."),
      supplyProfile("Water units",state.garden.water,"assets/science-worm-moisture-v1.png","Water moves through plant roots and helps transport dissolved substances."),
      supplyProfile("Tomato seeds",state.garden.seeds.tomato,"assets/science-fruit-week-review-v2.png","A seed contains a plant embryo and stored food for early growth."),
      supplyProfile("Pea seeds",state.garden.seeds.pea,"assets/science-seed-dispersal-v2.png","A pea seed can germinate into a climbing plant with tendrils."),
      supplyProfile("Sunflower seeds",state.garden.seeds.sunflower,"assets/science-bee-orchard-pollination-v1.png","A sunflower seed can grow into a tall plant with a compound flower head."),
      supplyProfile("Carrot seeds",state.garden.seeds.carrot,"assets/science-garden-nutrient-cycle-v1.png","A carrot stores food in a thick taproot below the soil.")
    ];
    vault.visibleProfiles=[...supplies,...research.map(profileFor),...adventure.map(profileFor),...materials.map(profileFor),...rewards];
    vault.root.scrollTop=0;vault.root.innerHTML=`<section class="treasure-vault-screen"><header class="vault-heading"><button id="vaultBack">← Cockpit</button><div><p>COCKPIT STORAGE · RESEARCH ARCHIVE</p><h1>Treasure Vault</h1><span>Tap any object to enlarge it and open its mini lesson.</span></div><strong>${research.length+adventure.length+rewards.length+materials.length} collected</strong></header>
      <section class="gem-workshop ${workshop.focus==="pilot"?"focus-pilot":""}"><div class="forge-visual" aria-hidden="true"><img src="assets/science-knowledge-crystal-v2.png" alt=""><i></i></div><div class="forge-copy"><p>KNOWLEDGE GEM WORKSHOP</p><h2>Forge five fragments into one complete Gem</h2><div class="fragment-meter"><span><i style="width:${Math.min(100,raw/5*100)}%"></i></span><b>${raw}/5 unused fragments</b></div><p>Each completed Gem receives a random colour, attribute and future upgrade use. Complete Gems can be exchanged for rare learning objects.</p><button id="forgeGem" ${raw<5?"disabled":""}>${raw<5?`${5-raw} more fragments needed`:"Forge a random Knowledge Gem"}</button></div><div class="gem-case"><small>AVAILABLE GEMS · ${gems.length}</small><div>${gems.map(gem=>`<button data-gem-id="${gem.id}" style="--gem:${gem.color}" title="${esc(gem.name)}"><i></i><span>${esc(gem.name)}</span></button>`).join("")||"<p>No complete Gems yet.</p>"}</div></div></section>
      <section class="vault-section exchange-section"><div class="vault-section-heading"><div><p>GEM EXCHANGE · MATHEMATICS SECURITY</p><h2>Unlock research objects</h2></div><span>Common 1 question · Rare 3 · Legendary 5</span></div><div class="exchange-grid">${CATALOG.map(item=>{const owned=!item.repeat&&workshop.owned.includes(item.id),enough=gems.length>=item.cost;return`<button class="exchange-card rarity-${item.rarity} ${owned?"owned":""}" data-exchange="${item.id}" style="--exchange-image:url('${item.image}')"><span class="exchange-art"></span><div><small>${item.rarity.toUpperCase()} · ${rarityQuestions(item.rarity)} MATH ${rarityQuestions(item.rarity)===1?"QUESTION":"QUESTIONS"}</small><h3>${esc(item.name)}</h3><p>${esc(item.ability)}</p><b>${owned?"✓ COLLECTED":enough?`💎 ${item.cost} COMPLETE GEM${item.cost===1?"":"S"}`:`LOCKED · NEED ${item.cost} GEM${item.cost===1?"":"S"}`}</b></div></button>`}).join("")}</div></section>
      ${rewards.length?`<section class="vault-section"><div class="vault-section-heading"><h2>💎 Gem Exchange Rewards</h2><span>${rewards.length} unlocked</span></div><div class="vault-grid">${rewards.map(item=>imageCard(item,"· EXCHANGED")).join("")}</div></section>`:""}
      <section class="vault-section"><div class="vault-section-heading"><h2>🔬 Knowledge & research</h2><span>${research.length} discoveries</span></div><div class="vault-grid"><button class="vault-item-card rarity-legendary" id="fragmentInfo"><span class="vault-item-image"><img src="assets/science-knowledge-crystal-v2.png" alt="Knowledge Crystal fragments"></span><small>KNOWLEDGE MATERIAL</small><strong>Crystal fragments × ${state.science.crystals||0}</strong><em>Inspect material →</em></button>${research.map(name=>imageCard(profileFor(name))).join("")||'<p class="vault-empty">Complete a science day to collect illustrated research objects.</p>'}</div></section>
      <section class="vault-section"><div class="vault-section-heading"><h2>🌿 Garden supplies</h2><span>Biology resources</span></div><div class="vault-grid">${supplies.map(profile=>imageCard(profile)).join("")}</div></section>
      <section class="vault-section"><div class="vault-section-heading"><h2>🚀 Adventure rewards</h2><span>${adventure.length} objects</span></div><div class="vault-grid">${adventure.map(name=>imageCard(profileFor(name))).join("")||'<p class="vault-empty">Adventure rewards will appear here.</p>'}</div></section>
      <section class="vault-section"><div class="vault-section-heading"><h2>◆ Materials & elements</h2><span>${materials.length} samples</span></div><div class="vault-grid">${materials.map(name=>imageCard(profileFor(name))).join("")||'<p class="vault-empty">Explore mines and events to collect materials.</p>'}</div></section>
      <div id="vaultModalHost"></div></section>`;
    document.getElementById("vaultBack").onclick=vault.onExit;document.getElementById("forgeGem").onclick=()=>forgeGem(vault);
    document.querySelectorAll("[data-vault-item]").forEach(button=>button.onclick=()=>openInfo(vault,vault.visibleProfiles.find(profile=>profile.name===button.dataset.vaultItem)||profileFor(button.dataset.vaultItem)));
    document.querySelectorAll("[data-exchange]").forEach(button=>button.onclick=()=>openExchange(vault,button.dataset.exchange));
    document.querySelectorAll("[data-gem-id]").forEach(button=>button.onclick=()=>openGem(vault,button.dataset.gemId));
    document.getElementById("fragmentInfo").onclick=()=>openInfo(vault,{id:"knowledge-fragment",name:"Knowledge Crystal Fragment",rarity:"legendary",image:"assets/science-knowledge-crystal-v2.png",origin:"Every completed Earth Research day",category:"Learning energy",ability:"Five fragments can be forged into one complete Knowledge Gem.",lesson:"A Knowledge Crystal fragment records evidence from one completed science investigation. Five fragments combine in the Gem Workshop, where their stored evidence forms one random Gem resonance.",facts:["Fragments are never lost unless they are forged into a complete Gem.","A complete Gem can unlock a research object or cockpit service."]});
    if(workshop.focus==="pilot"){workshop.focus="";vault.save();const pass=document.querySelector('[data-exchange="pilot-change"]');if(pass)later(vault,()=>pass.scrollIntoView({behavior:"smooth",block:"center"}),100)}
  }

  function forgeGem(vault){const {state}=vault;if(fragments(state)<5)return;const type=GEM_TYPES[Math.floor(Math.random()*GEM_TYPES.length)],gem={id:`gem-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,...type,forgedAt:Date.now(),usedBy:""};state.gemWorkshop.convertedFragments+=5;state.gemWorkshop.forged.push(gem);vault.save();openGem(vault,gem.id,true)}
  function openGem(vault,id,newGem=false){const gem=vault.state.gemWorkshop.forged.find(item=>item.id===id);if(!gem)return;modal(vault,`<article class="vault-modal-card gem-reveal" style="--gem:${gem.color}"><div class="large-gem"><i></i></div><p>${newGem?"NEW GEM FORGED":"KNOWLEDGE GEM RECORD"}</p><h2>${esc(gem.name)}</h2><div class="object-properties"><span><b>Attribute</b>${esc(gem.trait)}</span><span><b>Status</b>${gem.usedBy?`Used for ${esc(gem.usedBy)}`:"Available for exchange"}</span></div><p>${esc(gem.effect)}</p><button id="vaultModalClose">Return to vault</button></article>`);document.getElementById("vaultModalClose").onclick=()=>{closeModal(vault);render(vault)}}

  function openInfo(vault,profile){const key=`info:${profile.id||profile.name}`,first=!vault.state.gemWorkshop.seen.includes(key);modal(vault,`<article class="vault-modal-card object-lesson rarity-${profile.rarity||"common"}"><button class="modal-x" id="vaultModalClose" ${first?"disabled":""}>×</button><div class="object-hero"><img src="${esc(profile.image)}" alt="${esc(profile.name)} enlarged"></div><div class="object-copy"><p>${(profile.rarity||"common").toUpperCase()} OBJECT · MINI LESSON</p><h2>${esc(profile.name)}</h2><div class="object-properties"><span><b>Type</b>${esc(profile.category)}</span><span><b>Found at</b>${esc(profile.origin)}</span><span><b>Property</b>${esc(profile.ability)}</span></div><h3>What does it teach us?</h3><p>${esc(profile.lesson)}</p><div class="fun-facts"><b>FUN FACT${profile.facts?.length>1?"S":""}</b>${(profile.facts||[]).map(fact=>`<p>✦ ${esc(fact)}</p>`).join("")}</div><div class="read-lock" id="readLock">${first?"Read the record · closing unlocks in 5 seconds":"Record reviewed · you can close it now."}</div></div></article>`);const close=document.getElementById("vaultModalClose");close.onclick=()=>{if(close.disabled)return;if(!vault.state.gemWorkshop.seen.includes(key)){vault.state.gemWorkshop.seen.push(key);vault.save()}closeModal(vault)};if(first)unlockReading(vault,close,document.getElementById("readLock"))}
  function unlockReading(vault,button,label){let seconds=5;const tick=()=>{seconds--;if(active!==vault)return;if(seconds<=0){button.disabled=false;label.textContent="Record reviewed · you can close it now."}else{label.textContent=`Read the record · closing unlocks in ${seconds} seconds`;later(vault,tick,1000)}};later(vault,tick,1000)}

  function openExchange(vault,id){const item=CATALOG.find(entry=>entry.id===id);if(!item)return;if(!item.repeat&&vault.state.gemWorkshop.owned.includes(item.id))return openInfo(vault,item);const enough=availableGems(vault.state).length>=item.cost;modal(vault,`<article class="vault-modal-card exchange-intro rarity-${item.rarity}"><button class="modal-x" id="vaultModalClose" disabled>×</button><div class="exchange-intro-art"><img src="${esc(item.image)}" alt="${esc(item.name)}"></div><div><p>${item.rarity.toUpperCase()} EXCHANGE · ${rarityQuestions(item.rarity)} MATH ${rarityQuestions(item.rarity)===1?"QUESTION":"QUESTIONS"}</p><h2>${esc(item.name)}</h2><div class="object-properties"><span><b>Cost</b>${item.cost} complete Knowledge Gem${item.cost===1?"":"s"}</span><span><b>Found at</b>${esc(item.origin)}</span><span><b>Property</b>${esc(item.ability)}</span></div><h3>Read before unlocking</h3><p>${esc(item.lesson)}</p><div class="fun-facts">${item.facts.map(fact=>`<p>✦ ${esc(fact)}</p>`).join("")}</div><div class="exchange-actions"><button id="beginExchange" ${!enough?"disabled":""}>${enough?"Begin mathematics security check":`Need ${item.cost-availableGems(vault.state).length} more complete Gem${item.cost-availableGems(vault.state).length===1?"":"s"}`}</button><span id="readLock">Please read · controls unlock in 5 seconds</span></div></div></article>`);const close=document.getElementById("vaultModalClose"),begin=document.getElementById("beginExchange");close.onclick=()=>closeModal(vault);begin.onclick=()=>startChallenge(vault,item);unlockReading(vault,close,document.getElementById("readLock"));begin.disabled=true;later(vault,()=>{if(active===vault&&enough)begin.disabled=false},5000)}

  function startChallenge(vault,item){vault.challenge={item,needed:rarityQuestions(item.rarity),done:0,used:[],question:null,feedback:""};nextQuestion(vault)}
  function nextQuestion(vault){const challenge=vault.challenge,q=vault.getQuestion(challenge.used);if(!q){challenge.feedback="No text-only mathematics question is available right now.";return renderQuestion(vault)}challenge.question=q;challenge.used.push(q.id);challenge.feedback="";renderQuestion(vault)}
  function renderQuestion(vault){const challenge=vault.challenge,q=challenge.question;modal(vault,`<article class="vault-modal-card security-check"><div class="security-progress"><span>GEM SECURITY · ${challenge.item.rarity.toUpperCase()}</span><b>${challenge.done}/${challenge.needed} CORRECT</b></div><div class="security-dots" style="--count:${challenge.needed}">${Array.from({length:challenge.needed},(_,i)=>`<i class="${i<challenge.done?"done":""}"></i>`).join("")}</div>${q?`<small>${esc(q.paper)} · ${esc(q.skill)}</small><h2>${esc(q.prompt)}</h2><label>Answer<input id="vaultMathAnswer" autocomplete="off"></label><button id="vaultMathCheck">Check answer</button>`:""}<p class="security-feedback ${challenge.feedback?"bad":""}" id="securityFeedback">${esc(challenge.feedback||"Answer correctly to continue the exchange.")}</p></article>`);if(!q)return;const check=()=>checkChallenge(vault);document.getElementById("vaultMathCheck").onclick=check;document.getElementById("vaultMathAnswer").onkeydown=event=>{if(event.key==="Enter")check()};document.getElementById("vaultMathAnswer").focus()}
  function checkChallenge(vault){const challenge=vault.challenge,input=document.getElementById("vaultMathAnswer"),good=vault.checkAnswer(challenge.question.id,input.value);if(!good){challenge.feedback="Not correct yet. Check the numbers and try the same question again.";document.getElementById("securityFeedback").textContent=challenge.feedback;document.getElementById("securityFeedback").classList.add("bad");input.select();return}challenge.done++;if(challenge.done>=challenge.needed)return completeExchange(vault,challenge.item);challenge.feedback="Correct! Loading the next security question…";document.getElementById("securityFeedback").textContent=challenge.feedback;document.getElementById("securityFeedback").className="security-feedback good";later(vault,()=>nextQuestion(vault),650)}
  function completeExchange(vault,item){const gems=availableGems(vault.state);if(gems.length<item.cost){closeModal(vault);return render(vault)}const used=gems.slice(0,item.cost);used.forEach(gem=>gem.usedBy=item.name);let result=item.name;if(item.service==="pilot")result=`Pilot changed to ${vault.onPilotSwap()}`;else{if(!vault.state.gemWorkshop.owned.includes(item.id))vault.state.gemWorkshop.owned.push(item.id);if(!vault.state.inventory.includes(item.name))vault.state.inventory.push(item.name)}vault.save();modal(vault,`<article class="vault-modal-card exchange-complete rarity-${item.rarity}"><div class="reward-rays" aria-hidden="true"></div><div class="reward-object"><img src="${esc(item.image)}" alt="${esc(item.name)} unlocked"></div><p>EXCHANGE COMPLETE</p><h2>${esc(result)}</h2><div class="spent-gems">${used.map(gem=>`<span style="--gem:${gem.color}"><i></i>${esc(gem.name)}</span>`).join("")}</div><p>You read the field record and passed ${rarityQuestions(item.rarity)} mathematics ${rarityQuestions(item.rarity)===1?"question":"questions"}.</p><button id="vaultRewardClose">${item.service?"Return to vault":"Store object in chest"}</button></article>`);document.getElementById("vaultRewardClose").onclick=()=>{closeModal(vault);render(vault)}}

  function modal(vault,html){const host=document.getElementById("vaultModalHost");if(!host)return;host.innerHTML=`<div class="vault-modal" role="dialog" aria-modal="true">${html}</div>`;document.body.classList.add("vault-modal-open")}
  function closeModal(vault){const host=document.getElementById("vaultModalHost");if(host)host.innerHTML="";document.body.classList.remove("vault-modal-open");vault.challenge=null}
  function mount(options){destroy();const vault={...options,timers:new Set(),challenge:null};active=vault;render(vault)}
  function destroy(){if(!active)return;active.timers.forEach(clearTimeout);active.timers.clear();document.body.classList.remove("vault-modal-open");active=null}
  window.TreasureVault={mount,destroy};
})();
